-- Step 3: authentication and profile tables.
-- UUID primary keys are generated by the application, so no database extension is needed.

create table users (
    id uuid primary key,
    email varchar(320) not null,
    password_hash varchar(100),
    google_id varchar(255),
    role varchar(20) not null default 'USER',
    created_at timestamptz not null default now(),
    constraint users_email_unique unique (email),
    constraint users_google_id_unique unique (google_id),
    constraint users_role_check check (role in ('USER', 'ADMIN')),
    constraint users_identity_check check (password_hash is not null or google_id is not null)
);

create table profiles (
    user_id uuid primary key references users (id) on delete cascade,
    nickname varchar(50) not null,
    avatar varchar(100),
    language varchar(5) not null default 'en',
    level_of_study varchar(50),
    timezone varchar(64) not null default 'Asia/Phnom_Penh',
    daily_goal_cards integer not null default 10,
    daily_goal_minutes integer not null default 10,
    updated_at timestamptz not null default now(),
    constraint profiles_language_check check (language in ('en', 'km')),
    constraint profiles_goal_cards_check check (daily_goal_cards between 1 and 500),
    constraint profiles_goal_minutes_check check (daily_goal_minutes between 1 and 600)
);

create table refresh_tokens (
    id uuid primary key,
    user_id uuid not null references users (id) on delete cascade,
    token_hash varchar(64) not null,
    expires_at timestamptz not null,
    revoked boolean not null default false,
    created_at timestamptz not null default now(),
    constraint refresh_tokens_hash_unique unique (token_hash)
);

create index idx_refresh_tokens_user on refresh_tokens (user_id);
create index idx_refresh_tokens_expires on refresh_tokens (expires_at);

create table password_reset_tokens (
    id uuid primary key,
    user_id uuid not null references users (id) on delete cascade,
    token_hash varchar(64) not null,
    expires_at timestamptz not null,
    used boolean not null default false,
    created_at timestamptz not null default now(),
    constraint password_reset_tokens_hash_unique unique (token_hash)
);

create index idx_password_reset_tokens_user on password_reset_tokens (user_id);
create index idx_password_reset_tokens_expires on password_reset_tokens (expires_at);
